127→	// the original directory when the benchmark function returns.
128→	b.Chdir(dir)
129→	paths.ClearWorktreeRootCache()
130→
131→	// Set up each session with a shadow branch checkpoint
132→	modifiedFiles := []string{"src/file_0.go", "src/file_1.go"}
133→	for i := range sessionCount {
134→		sessionID := fmt.Sprintf("bench-session-%d", i)
135→
136→		// Modify files with agent content
137→		for _, f := range modifiedFiles {
138→			abs := filepath.Join(dir, f)
139→			content := fmt.Sprintf("package main\n// modified by agent session %d\nfunc f() {}\n", i)
140→			if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
141→				b.Fatalf("write: %v", err)
142→			}
143→		}
