172→		}
173→
174→		// Set the session phase
175→		state, err := s.loadSessionState(context.Background(), sessionID)
176→		if err != nil {
177→			b.Fatalf("load state: %v", err)
178→		}
179→		state.Phase = phase
180→		state.FilesTouched = modifiedFiles
181→		if err := s.saveSessionState(context.Background(), state); err != nil {
182→			b.Fatalf("save state: %v", err)
